inbound.set-body:
@{
            // Read the incoming REST JSON body
            var body = context.Request.Body.As(preserveContent: true);

            // Build the GraphQL mutation string
            var graphqlQuery = @"
                mutation ConfirmCheckout($confirmRequest: CheckoutConfirmRequest!) {
                    ConfirmCheckout(input: $confirmRequest) {
                        orderId
                        pnrId
                        pricing {
                            total { value currencyCode }
                        }
                        connections {
                            origin { airportCode }
                            destination { airportCode }
                            departureDateTime
                            flightNumber
                        }
                        passengers {
                            id
                            identityDetails {
                                firstName
                                lastName
                            }
                        }
                        services {
                            id
                            name
                            quantity
                            pricing {
                                total { value currencyCode }
                            }
                        }
                    }
                }";

            // Compose the full GraphQL request payload
            var graphqlPayload = new JObject(
                new JProperty("query", graphqlQuery),
                new JProperty("variables", new JObject(
                    new JProperty("confirmRequest", body)
                ))
            );

            return graphqlPayload.ToString();
        }

outbound.set-body:
@{
            var response = context.Response.Body.As(preserveContent: true);
            var confirmCheckout = response["data"]?["ConfirmCheckout"];
            return confirmCheckout != null ? confirmCheckout.ToString() : response.ToString();
        }
